-- ============================================================
-- Demo seed data generated by scripts/generate_seed_demo.py
-- 100 users / 50 goods / ~400 orders, 2026-01 ~ 2026-08
-- ============================================================
\connect shop_user
BEGIN;
DELETE FROM user_addresses WHERE user_id BETWEEN 1001 AND 1100;
DELETE FROM users WHERE id BETWEEN 1001 AND 1100;
SELECT setval('users_id_seq', GREATEST((SELECT MAX(id) FROM users), 1));
SELECT setval('user_addresses_id_seq', GREATEST((SELECT MAX(id) FROM user_addresses), 1));
COMMIT;
\connect shop_goods
BEGIN;
DELETE FROM goods_images WHERE goods_id BETWEEN 1001 AND 1050;
DELETE FROM goods_inventories WHERE sku_id BETWEEN 1001 AND 1050;
DELETE FROM goods_specification_skus WHERE sku_id BETWEEN 1001 AND 1050;
DELETE FROM goods_skus WHERE id BETWEEN 1001 AND 1050;
DELETE FROM goods WHERE id BETWEEN 1001 AND 1050;
DELETE FROM goods_type_brands WHERE brand_id BETWEEN 1001 AND 1016;
DELETE FROM goods_category_brands WHERE category_id BETWEEN 1001 AND 1005;
DELETE FROM goods_types WHERE id BETWEEN 1001 AND 1005;
DELETE FROM brands WHERE id BETWEEN 1001 AND 1016;
DELETE FROM categories WHERE id BETWEEN 1001 AND 1005;
COMMIT;
\connect shop_order
BEGIN;
DELETE FROM order_goods WHERE order_sn LIKE 'DEMO%';
DELETE FROM order_pays WHERE order_sn LIKE 'DEMO%';
DELETE FROM order_address WHERE order_sn LIKE 'DEMO%';
DELETE FROM orders WHERE order_sn LIKE 'DEMO%';
SELECT setval('orders_id_seq', GREATEST((SELECT MAX(id) FROM orders), 1));
SELECT setval('order_address_id_seq', GREATEST((SELECT MAX(id) FROM order_address), 1));
SELECT setval('order_goods_id_seq', GREATEST((SELECT MAX(id) FROM order_goods), 1));
SELECT setval('order_pays_id_seq', GREATEST((SELECT MAX(id) FROM order_pays), 1));
COMMIT;
\connect shop_inventory
BEGIN;
DELETE FROM inventories WHERE sku_id BETWEEN 1001 AND 1050;
SELECT setval('inventories_id_seq', GREATEST((SELECT MAX(id) FROM inventories), 1));
COMMIT;
